import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
  Easing,
} from '../remotionShim';
// Required Font Loader Hook
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Sub-components ---

const Heart = ({
  color,
  progress,
  xOffset,
  scale,
  sway,
}: {
  color: string;
  progress: number;
  xOffset: number;
  scale: number;
  sway: number;
}) => {
  // progress 0 -> 1 (lifetime of particle)
  // Fade in quickly, fade out slowly
  const opacity = interpolate(progress, [0, 0.1, 0.8, 1], [0, 1, 1, 0]);
  
  // Move upwards
  const translateY = interpolate(progress, [0, 1], [0, -600]);
  
  // Sway left/right
  const translateX = Math.sin(progress * Math.PI * 4) * sway + xOffset;
  
  // Scale up initially
  const currentScale = interpolate(progress, [0, 0.2], [0, scale], {
    extrapolateRight: "clamp",
  });

  if (progress <= 0 || progress >= 1) return null;

  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        transform: `translate(${translateX}px, ${translateY}px) scale(${currentScale})`,
        opacity,
      }}
    >
      <svg
        width="50"
        height="50"
        viewBox="0 0 24 24"
        fill={color}
        style={{ overflow: "visible" }}
      >
        <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
      </svg>
    </div>
  );
};

// --- Schema & Main Component ---



export type GiftBoxHeartsProps = Record<string, any>;

const GiftBoxHearts: React.FC<GiftBoxHeartsProps> = ({
  backgroundColor = "#fdf2f8",
  transparentBackground = false,
  durationInSeconds = 6,
  boxColor = "#ef4444",
  ribbonColor = "#fcd34d",
  heartColor = "#ec4899",
  heartCount = 20,
  lidDelay = 1.0,
}) => {
  // Load fonts (just in case, keeps structure consistent)
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Derived Values
  const actualBgColor = transparentBackground ? "transparent" : backgroundColor;
  const startOpenFrame = lidDelay * fps;

  // --- Animation Physics ---

  // 1. Box Entrance (Scale Spring)
  const entrance = spring({
    frame,
    fps,
    config: { damping: 12 },
    durationInFrames: 30,
  });

  // 2. Shake/Anticipation before opening
  const shakeProgress = interpolate(
    frame,
    [startOpenFrame - 15, startOpenFrame - 10, startOpenFrame - 5, startOpenFrame],
    [0, -5, 5, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  // Squash effect before pop
  const squashY = interpolate(
    frame,
    [startOpenFrame - 10, startOpenFrame],
    [1, 0.9],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const squashX = interpolate(
    frame,
    [startOpenFrame - 10, startOpenFrame],
    [1, 1.05],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 3. Lid Opening (Pop off)
  const lidTrigger = frame - startOpenFrame;
  const lidY = spring({
    frame: lidTrigger,
    fps,
    config: { stiffness: 80, damping: 15 },
  });
  
  const lidMoveY = interpolate(lidY, [0, 1], [0, -300]);
  const lidRotate = interpolate(lidY, [0, 1], [0, -15]);
  const lidOpacity = interpolate(lidTrigger, [0, 10], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }); // Fade out lid eventually or keep it flying? Let's keep it visible but flying away.
  
  // Refined Lid Move: Fly up and fade slightly
  const lidFlyUp = interpolate(
    lidTrigger,
    [0, 40],
    [0, -800], // Fly off screen
    { extrapolateLeft: "clamp", easing: Easing.back(1.5) }
  );

  // 4. Box Body Reaction (Recoil down then settle)
  const bodyRecoil = spring({
    frame: lidTrigger,
    fps,
    config: { stiffness: 150, damping: 10 },
  });
  const bodyY = interpolate(bodyRecoil, [0, 0.5, 1], [0, 20, 0]);

  // 5. Hearts Generation
  const hearts = useMemo(() => {
    return new Array(heartCount).fill(0).map((_, i) => {
      const seed = i * 452.12; // Deterministic random
      const delayFrames = random(seed) * 30; // Random delay up to 1s
      const xPos = (random(seed + 1) - 0.5) * 200; // Spread -100 to 100
      const scale = 0.5 + random(seed + 2) * 1.5; // Scale 0.5 to 2.0
      const sway = 20 + random(seed + 3) * 30;
      const speed = 60 + random(seed + 4) * 60; // Duration in frames
      
      return {
        id: i,
        delayFrames,
        xPos,
        scale,
        sway,
        speed,
      };
    });
  }, [heartCount]);

  // --- Styles ---

  const boxSize = 200;
  const lidHeight = 50;
  const lidOverhang = 20;

  return (
    <AbsoluteFill style={{ backgroundColor: actualBgColor }}>
      <div
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          width: "100%",
          height: "100%",
          perspective: "1000px", // Adds depth
        }}
      >
        {/* Main Wrapper for scaling entrance */}
        <div
          style={{
            position: "relative",
            transform: `scale(${entrance}) rotate(${shakeProgress}deg)`,
          }}
        >
          {/* HEARTS LAYER (Behind front of box, technically spawning from center) */}
          <div
            style={{
              position: "absolute",
              top: 0, // Top of the box body
              left: boxSize / 2, // Center horizontally
              width: 0,
              height: 0,
              zIndex: 0, // Behind the box body
            }}
          >
            {hearts.map((h) => {
              const heartFrameStart = startOpenFrame + h.delayFrames;
              if (frame < heartFrameStart) return null;
              
              const lifeProgress = (frame - heartFrameStart) / h.speed;
              
              return (
                <Heart
                  key={h.id}
                  color={heartColor}
                  progress={lifeProgress}
                  xOffset={h.xPos}
                  scale={h.scale}
                  sway={h.sway}
                />
              );
            })}
          </div>

          {/* BOX BODY */}
          <div
            style={{
              width: boxSize,
              height: boxSize,
              backgroundColor: boxColor,
              position: "relative",
              borderRadius: "4px",
              boxShadow: "0 10px 20px rgba(0,0,0,0.15)",
              transform: `scale(${squashX}, ${squashY}) translateY(${bodyY}px)`,
              zIndex: 10,
              display: "flex",
              justifyContent: "center",
              overflow: "hidden", // Clip ribbon inside
            }}
          >
             {/* Vertical Ribbon Body */}
             <div
              style={{
                width: boxSize * 0.2,
                height: "100%",
                backgroundColor: ribbonColor,
              }}
            />
          </div>

          {/* BOX LID */}
          <div
            style={{
              width: boxSize + lidOverhang,
              height: lidHeight,
              backgroundColor: boxColor, // Slightly darker typically, but using same base
              filter: "brightness(1.1)", // Highlight lid
              position: "absolute",
              top: -lidHeight + 5, // Overlap slightly
              left: -lidOverhang / 2,
              borderRadius: "4px",
              boxShadow: "0 5px 15px rgba(0,0,0,0.1)",
              zIndex: 20,
              display: "flex",
              justifyContent: "center",
              transformOrigin: "bottom left",
              transform: `translateY(${lidFlyUp}px) rotate(${lidRotate}deg)`,
            }}
          >
            {/* Horizontal Ribbon Lid */}
            <div
              style={{
                position: "absolute",
                top: "50%",
                left: 0,
                width: "100%",
                height: boxSize * 0.2,
                marginTop: -(boxSize * 0.2) / 2,
                backgroundColor: ribbonColor,
              }}
            />
             {/* Vertical Ribbon Lid */}
            <div
              style={{
                width: boxSize * 0.2,
                height: "100%",
                backgroundColor: ribbonColor,
              }}
            />
             {/* Bow Knot */}
             <div 
                style={{
                    position: 'absolute',
                    top: -20,
                    width: 40,
                    height: 20,
                    backgroundColor: ribbonColor,
                    borderRadius: 10,
                    boxShadow: '0 2px 4px rgba(0,0,0,0.2)'
                }}
             />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default GiftBoxHearts;